    nestedTypes: <String>[
      'HealthCheckType',
      'HealthCheckProxyHeader',
      'HealthCheckPortSpecification',
      'ComputeHealthCheckProtocol',
      'ComputeHealthCheckHttpHealthCheckConfig',
      'ComputeHealthCheckHttpsHealthCheckConfig',
