  CatalogEntry(
    tfType: 'google_firebase_app_check_resource_policy',
    className: 'GoogleFirebaseAppCheckResourcePolicy',
    barrel: 'firebase_app_check',
    kind: CatalogKind.resource,
    summary:
        'Factory wrapper for `google_firebase_app_check_resource_policy` (provider `hashicorp/google ~> 7.0`).',
    constructorParams: <String>[
